def build_agent(sandbox):
    # No need to build additional structures; the agent is already initialized
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    global unlock_counter  # Track unlock progress across steps

    # Initialize unlock counter if not already set
    if 'unlock_counter' not in globals():
        unlock_counter = 0

    pos = sandbox.get_agent_position()
    front, up, down = sandbox.get_whisker_readings()
    vel = sandbox.get_agent_velocity()

    # Constants
    MAX_FORCE = 30.0  # Adjust based on environment dynamics
    UNLOCK_FX = -35.0
    UNLOCK_SPEED_LIMIT = 100.0
    UNLOCK_STEPS = 5

    # Check if in whisker-blind zone (front whisker near max range)
    if front >= 2.9:  # Tolerance for max range (3.0m)
        # Apply forward force to move toward unlock zone
        fx = MAX_FORCE
        fy = 0.0
    else:
        # Check if in unlock zone
        if 5.0 <= pos[0] <= 10.0:
            # Apply unlock force if speed is within limit
            if vel[0] < UNLOCK_SPEED_LIMIT:
                fx = UNLOCK_FX
                unlock_counter += 1
            else:
                # Reduce force to lower speed
                fx = -20.0
                unlock_counter = 0
        else:
            # Navigate toward unlock zone
            if pos[0] < 5.0:
                # Move forward
                fx = MAX_FORCE
            elif pos[0] > 10.0:
                # Move backward
                fx = -MAX_FORCE
            else:
                # Use whiskers to adjust direction
                if front < 0.5:
                    # Turn right to avoid wall
                    fx = MAX_FORCE
                else:
                    # Move forward
                    fx = MAX_FORCE
            fy = 0.0

    # After unlock, navigate to exit zone
    if unlock_counter >= UNLOCK_STEPS:
        if pos[0] < 15.0:
            fx = MAX_FORCE
        else:
            fx = 0.0
        fy = 0.0

    # Apply calculated forces
    sandbox.apply_agent_force(fx, fy)
